RAIDAS_IMG = [('चंदन', 'पानी'), ('घन (बादल)', 'मोर'), ('चंद्र', 'चकोर'), ('दीपक', 'बाती'), ('मोती', 'धागा'), ('सोना', 'सुहागा'), ('स्वामी', 'दास')]


def raidas_pair(r):
    p, b = r.choice(RAIDAS_IMG)
    wrong = [x[1] for x in RAIDAS_IMG if x[1] != b]
    return mcq(f'रैदास के पद "अब कैसे छूटै राम नाम रट लागी" में यदि प्रभु "{p}" हैं, तो भक्त स्वयं को क्या कहते हैं?', b, r.sample(wrong, 3),
               f'प्रभु {p}, भक्त {b}—इस जोड़ी से प्रभु और भक्त का अटूट संबंध प्रकट होता है।', r)


